import java.util.Scanner;
public class JNestedIfTemperature1 {
	public static void main(String[] args) {
		//Khatwa 1: Iqra' darajat al-harara li al-yawm wa al-ams
		Scanner scan = new Scanner (System.in);
		System.out.println("Adkhil darajat al-harara li al-ams: ");
		double yesterday = scan.nextDouble();
		System.out.println("Adkhil darajat al-harara li al-yawm: ");
		double today = scan.nextDouble();		
		scan.close();
		//Khatwa 2: Nuhadhir al-mustakhdim bial-taghyirat fi darajat al-harara
		if ( today < yesterday ) {
			System.out.println("Innahu yusbihu abrad!");
		} else {
			if ( today > yesterday ) {
				System.out.println("Innahu yusbihu adfa'!");
			} else {
				System.out.println("Darajat al-harara nafsuha ka al-ams!");
			}
		}
	}
}
